    "transportInfo.button": "Explain the modes of transport",
    "transportInfo.button.title": "How fast each mode of transport is: on every way type, on slopes and in the air",
    "transportInfo.intro":
        "How fast a journey goes depends on the mode of transport *and* the way type. A group on foot makes {road} miles an hour on an imperial road, but only {pass} on a mountain pass. The tables give the miles per day and the pace in miles per hour (1 mile = 1,000 paces, about 1 km).",
