    "planner.cost.fn.source":
        "Bed, board and fodder come from the DSA5 core rules and the Kodex der Helden. 1 Dukat = 10 Silbertaler = 100 Heller.",
    "planner.cost.fn.geographia": "Tolls and passage follow the Geographia Aventurica.",
    // Why nights cost nothing although an inn is chosen: the day's travel ends on a way that offers no roof. 🔴 No address
    // (“you”): the rule is stated, not said to the reader (operator 2026-10-04).
    "planner.cost.fn.open":
        "A party sleeps outdoors when the day's travel ends on a trail, pass, desert trail or cross-country.",
    "planner.cost.fn.aboard":
        "A party sleeps aboard when the day's travel ends on a river or the sea; the berth is part of the passage.",
