    "inhalte.info.text":
        "This window maintains the content that is not map objects. A source is a shared catalog entry; its uses belong to the individual objects. A work of literature carries its ordered start and play locations. An occurrence (fauna, flora, goods, species) carries its places with a match preview and its rules read-only. What comes from Legacy or the wiki stays marked as such; a changed value is protected before the next sync. A corpus is the offering behind the sources of a domain; for a citation source its details apply to all sources of the domain.",
