    "inhalte.vorkommen.text.ref.quelle.name": "Source",
    "inhalte.vorkommen.text.ref.quelle.text":
        "applies to all following entries up to the next Quelle line; “Quelle: –” ends it. The pages follow “, S.”.",
    "inhalte.vorkommen.text.ref.kopf.name": "Head",
    "inhalte.vorkommen.text.ref.kopf.text":
        "Name at the start of the line; category in parentheses. Entries with the same name: “(Flora, [[Wiki-Titel]])”. If the entry does not exist: “(Flora, neu)”.",
    "inhalte.vorkommen.text.ref.regel.name": "Rule",
    "inhalte.vorkommen.text.ref.regel.text":
        "A line “| Beziehung = Ausdruck” like a parameter of the wiki infobox (Verbreitung, Herkunft, Regionen, Vorkommen); it may appear several times. An indented line without “|” continues the expression of the line above.",
    "inhalte.vorkommen.text.ref.zeichen.name": "Signs",
    "inhalte.vorkommen.text.ref.zeichen.neueRegel": "new rule",
    "inhalte.vorkommen.text.ref.zeichen.oder": "or",
    "inhalte.vorkommen.text.ref.zeichen.und": "and",
    "inhalte.vorkommen.text.ref.zeichen.ohne": "without",
    "inhalte.vorkommen.text.ref.zeichen.gilt": "Signs only count outside “[[…]]” and “(…)”.",
    "inhalte.vorkommen.text.ref.glied.name": "Term",
    "inhalte.vorkommen.text.ref.glied.text":
        "Between the signs stands a term, and a term is one condition of the rule editor. Its parts come in any order, each at most once:",
    "inhalte.vorkommen.text.ref.arten.name": "Landscape types",
    "inhalte.vorkommen.text.ref.arten.oder": "(OR among them)",
    "inhalte.vorkommen.text.ref.flaeche.name": "Area",
    "inhalte.vorkommen.text.ref.flaeche.ohneIn":
        "without “in” if the name is not a landscape type (the areas “Meer” and “See” need “in”)",
    "inhalte.vorkommen.text.ref.flaeche.mehrdeutig": "for an ambiguous name",
    "inhalte.vorkommen.text.ref.flaeche.wartet": "(the area does not exist yet)",
    "inhalte.vorkommen.text.ref.klima.name": "Climate",
    "inhalte.vorkommen.text.ref.lage.name": "Position",
    "inhalte.vorkommen.text.ref.lage.zwischen": "(between the places “–”, “-” or “bis”)",
    "inhalte.vorkommen.text.ref.namen":
        "Names always stand in “[[…]]” (landscape types, areas, places, sources); that is why they may contain a comma, colon, hyphen and “und”. “[[Ziel|Anzeige]]” and attached letters (“[[Steppe]]n”) are allowed; the target counts. An area is found first by its wiki title, then by its name; if that is ambiguous, the preview asks and writes “[[#Kennung|Name]]”. Parenthetical additions exist only as “(wartet)”. Upper and lower case, ß/ss and accents do not count in the comparison as long as the result stays unambiguous. There is an upper limit per rule and per entry; the finding names it. A click on a word inserts it at the cursor.",
    "inhalte.vorkommen.text.ref.unterschied.kopf": "One difference from the wiki:",
    "inhalte.vorkommen.text.ref.unterschied.text":
        "Strictly from left to right, without precedence: “[[A]], [[B]]: [[C]]” means “(A or B) and C” and “[[A]] außer [[X]], [[B]]” means “(A without X) or B”. The wiki reads “A, B: C” differently, namely as “A, or C in B”: there only the last term before the colon is the frame. Where the frame comes first (“[[Aventurien]]: [[Meridiana]], [[Orkland]]”), both read the same.",
    "inhalte.vorkommen.text.n.eintraege.one": "{n} entry",
    "inhalte.vorkommen.text.n.eintraege.other": "{n} entries",
    "inhalte.vorkommen.text.n.eintraegeAn.one": "{n} entry",
    "inhalte.vorkommen.text.n.eintraegeAn.other": "{n} entries",
    "inhalte.vorkommen.text.n.regeln.one": "{n} rule",
    "inhalte.vorkommen.text.n.regeln.other": "{n} rules",
    "inhalte.vorkommen.text.n.rueckfragen.one": "{n} question",
    "inhalte.vorkommen.text.n.rueckfragen.other": "{n} questions",
    "inhalte.vorkommen.text.n.fehler.one": "{n} error",
    "inhalte.vorkommen.text.n.fehler.other": "{n} errors",
    // Vorkommen ohne Wiki-Artikel (WI-0254, Runde 3b, Vali wählte B).
