    // --- Corner and notes ---
    "corner.news": "News",

    // --- Neuigkeiten (WI-0139) ---
    "news.title": "News",
    "news.intro":
        "What has happened on Avesmaps since the map went online in April 2026 — the bigger steps, without the fine print.",
    "news.foot":
        "Avesmaps is a fan project and is being built on continuously. Ideas and bugs are welcome on our Discord.",
    "news.loading": "Loading …",
    "news.failed": "The news could not be loaded.",
    "news.empty": "Nothing here yet.",
    "news.new": "new",
    "news.rubrik.karte": "Map",
    "news.rubrik.routenplaner": "Route planner",
    "news.rubrik.inhalte": "Content",
    "news.rubrik.community": "Community",
    "news.rubrik.programm": "Program",
    "news.rubrik.ki": "AI",
    "corner.notes": "Notices",
    "notes.title": "Notices",
    "notes.keyboard": "Keyboard",
    "notes.or": "or",
    "notes.shortcutsOff":
        "Turn off shortcuts with single letters, digits and characters. The arrow keys keep working. Helps when the map is controlled by voice.",
    "notes.ringText":
        "The right mouse button never moves the map. On a computer the control ring at the top right zooms (+, −), turns to the next cardinal direction with the arrows on its left and right and faces north in the middle; the “2D | 3D” pill above it tilts the map and flattens it again. On a phone two fingers do this; when the map is rotated, a compass appears there, and a tap on it puts north up. The round button with the map tile tilts the map into 3D and flattens it again.",
    "notes.ringOnTouch":
        "Also show the control ring on a phone. Then the map can be rotated and zoomed without two fingers.",
    // "Maps on Avesmaps" has replaced the separate "Map material" and "Map series" since 2026-10-12.
    "notes.derivationUndocumented":
        "How this version was derived from the original map is expressly not documented. The series is used locally; whether it is delivered publicly is decided separately.",
    "notes.badge": "Non-commercial fan project",
    "notes.badge.alt": "DSA fan project logo",
