        "How many rounds water and slope work on the terrain. More rounds cut deeper valleys and take longer.",
    "admin.terrain.test.reglerSatz.streamPowerK":
        "How strongly flowing water wears away the ground. Twice as much digs valleys noticeably deeper in the same time.",
    "admin.terrain.test.reglerSatz.diffusion":
        "How much slopes slide down and edges soften. Larger rounds off ridges and valleys.",
