    "admin.terrain.test.regler.wirkt.unruhe":
        "Works for all mountains. The pattern stays off the ridge itself and acts on the flanks.",
    "admin.terrain.test.regler.wirkt.koernung":
        "Works for all mountains. The size of the bumps is the length of the mountains divided by the number; the ridge-network type value (size in map units) is overridden by it.",
    "admin.terrain.test.regler.wirkt.muster": "Works for all mountains.",
