    "admin.terrain.test.wert.p.hypsometrie":
        "How high the land between the peaks lies: low gives points with deep valleys, high a broad base the peaks rise from. Above it is called massiveness.",
    "admin.terrain.test.wert.p.plateau":
        "With drawn ridges the sharpness of the ridge line (1 sharp as a blade, 0 round like a hill back); without them the share of plateau (1 only the central axis, smaller broader up to a table).",
    "admin.terrain.test.wert.p.rauschen":
        "How bumpy and rough the slopes are: 0 is smooth, high values make them wildly furrowed. Above the value is called unevenness.",
    "admin.terrain.test.wert.p.einschnitt":
        "How deeply rivers and lakes cut into the land, in paces. Without a river or lake in the mountains nothing changes.",
    "admin.terrain.test.wert.p.erosion":
        "How long the water digs at the slope in the mountain preview (levels 0 to 5): the higher, the more and deeper channels. Above the value is called channel erosion.",
    "admin.terrain.test.wert.p.talbreite":
        "How far a valley opens around a river, as half-width in map units. Only matters at rivers and lakes.",
    "admin.terrain.test.wert.p.koernung":
        "How many rises line up along the longest side of a mountain range: a few large bumps or many small ones. Above the value is called grain.",
    "admin.terrain.test.wert.p.stufen":
        "How fine the unevenness is: each level puts smaller bumps on the larger ones; 1 is soft and even, 8 grainy down to the smallest detail.",
    "admin.terrain.test.wert.p.bergform":
        "With drawn ridges the point of the peaks (small values blunt, large ones needle-slim); without them the reach with which a summit cone spreads into the surroundings, in map units.",
    "admin.terrain.test.wert.p.sattel":
        "How far a drawn ridge sags between two peaks: 1 keeps the height, 0.3 lowers it to 30 % of the peak height. Works in addition to the sag of the ridges.",
    "admin.terrain.test.wert.n.struktur.welle":
        "How long the gentle rises and dips along a ridge are, in map units. The height varies by only about 5 % in doing so.",
    "admin.terrain.test.wert.n.struktur.astAbstand":
        "At what spacing a drawn ridge gets side branches, in map units. 0 means no branches.",
    "admin.terrain.test.wert.n.struktur.astLaenge":
        "How far the side branches reach into the land, as a share of the way to the edge or the next ridge.",
    "admin.terrain.test.wert.n.form.breite":
        "How wide a mountain ridge spreads at its foot, as half-width in map units: narrow like a blade or broad like an old stump.",
    "admin.terrain.test.wert.n.form.schaerfe":
        "Whether the ridge line is round or sharp. Today the V12 value (ridge sharpness above) applies instead, as long as the preset carries one.",
    "admin.terrain.test.wert.n.form.talboden":
        "How high the land between the ridges lies, as a share of the ridge height. The terrain derives it from the massiveness; only the coarse preview calculates with it directly.",
    "admin.terrain.test.wert.n.form.rauschen":
        "How bumpy the slopes are. Today the V12 value (unevenness above) applies instead, as long as the preset carries one.",
    "admin.terrain.test.wert.n.form.koernung":
        "How large the largest bumps are, in map units. Today the number of rises from the V12 (grain above) applies instead, as long as the preset carries it.",
    "admin.terrain.test.wert.n.form.randBreite":
        "Over how many map units the mountains taper to zero toward their edge.",
    "admin.terrain.test.wert.n.form.erosion":
        "How much channel erosion the mountain preview calculates (levels 0 to 5). Today the V12 value (channel erosion above) applies instead, as long as the preset carries one.",
    "admin.terrain.test.wert.n.form.erhalt":
        "How much of the drawn shape remains after erosion: 0 lets only the erosion count, 1 lets none through. On the ridges more is kept besides.",
    "admin.terrain.test.wert.n.form.grat":
        "How deep a groove beside the ridge line lies (share of the ridge height), so that every drawn ridge stays visible as an arête.",
    "admin.terrain.test.wert.n.form.gratBreite":
        "How narrow the ridge line itself is, in map units; the groove lies beside it. Visible only when the ridge line is above 0.",
    "admin.terrain.test.wert.n.form.kopf":
        "How far a side peak must at least rise above the saddle to its neighbouring peak (share of the ridge height). Above the value is called height of side peaks.",
    "admin.terrain.test.wert.n.form.kammMuster":
        "How much of the base pattern (noise or cells) remains on the ridge itself: 0 keeps the drawn height, 1 lets the pattern act there too. On the flanks it always applies.",
    "admin.terrain.test.wert.n.form.kopfNeigung":
        "How steep the cone of a side peak is; the radius follows from the height. 0 keeps the head as a point as before. Above the value is called steepness of side peaks.",
    "admin.terrain.test.wert.n.form.durchhang":
        "How deeply a main ridge sags between two peaks, as a share of its height. Above the value is called sag of the ridges.",
    "admin.terrain.test.wert.n.form.durchhangNeben":
        "The same for the side ridges; in the presets they sag a third more. The sag slider above sets both together.",
    "admin.terrain.test.wert.n.form.gelaendeErosion":
        "How much erosion still works on the mountains in the finished terrain: 0 keeps the preview, 1 erodes fully.",
    "admin.terrain.test.wert.n.band.ziel":
        "How high the land should lie on average (share of the ridge height): the target the terrain uses to find the valley floor when the hypsometry is 0. Usually the massiveness applies instead.",
    "admin.terrain.test.wert.n.gratMin":
        "How much ridge definition the search for the valley floor leaves the drawn ridges at least: it lowers the valley floor until the ridges keep this sharpness (share of the ridge height).",
