    "admin.zoombaender.leadFirst": "A zoom band is a limit, not a guarantee.",
    "admin.zoombaender.lead":
        "Outside its range a type never appears. Inside it, the map may still hide a symbol or a name, for example when it collides with another one.",
    "admin.zoombaender.intro":
        "From which band to which band each type appears on the map: 0 is all of Aventuria, 8 is very close. A range applies to all objects of this type and takes precedence over the default from Legacy or the code; ↺ returns to the default. Filled is where the type appears; the default has a dotted outline.",
